"""Module for ConnectionUDS class."""

from .connection import Connection
import ncclient.manager


class ConnectionUDS(Connection):
    """ConnectionUDS Module"""

    def call_home_ssh_with_custom_timeout(self, *args, **kwds):
        """Call home ssh with custom timeout method"""
        raise NotImplementedError

    def connect_ssh(self, session: str):
        """Connect SSH"""
        raise NotImplementedError

    def call_home_ssh(self, session: str):
        """Call home ssh method."""
        raise NotImplementedError

    def close_all_sessions(self, closing_socket_only: bool = False):
        """Close all sessions."""
        raise NotImplementedError

    def _close_socket(self):
        """Close all sockets (connections and server)."""
        raise NotImplementedError

    def call_home_tls(self, session: str):
        """Call Home using TLS"""
        raise NotImplementedError

    def connect_tls(self, session: str):
        """Connect using TLS."""
        raise NotImplementedError

    def call_home(self, netconf_server_socket_name: str):
        """Representative method for initializing call home via UDS.

        Connect to the netconf server via UDS can be established only for unix-like systems.
        :param netconf_server_socket_name: Name of the UDS socket to connect to.
        """
        self.sessions["master_0"] = ncclient.manager.connect_uds(
            netconf_server_socket_name, device_params={"name": "rfsw"}
        )
